SELECT segment, segment_group, stddev_age FROM (SELECT segment, CASE WHEN segment IN ('Consumer', 'Corporate') THEN 'priority' ELSE 'other' END AS segment_group, ROUND(STDDEV(age), 2) AS stddev_age FROM customers WHERE LENGTH(email) >= 12 GROUP BY segment, CASE WHEN segment IN ('Consumer', 'Corporate') THEN 'priority' ELSE 'other' END) AS s WHERE stddev_age < 40 ORDER BY stddev_age DESC, segment_group DESC, segment ASC LIMIT 20
